-- personality_assessment_questions
INSERT INTO public.personality_assessment_questions (id, question_number, question_text, question_category, trait, reverse_scored, assessment_version, is_active, created_at, updated_at) SELECT id, question_number, question_text, question_category, trait, reverse_scored, assessment_version, is_active, created_at, updated_at FROM jsonb_populate_recordset(NULL::public.personality_assessment_questions, '[{"id": "1a6b2025-a530-4a3f-b740-452198c18fc7", "trait": "conscientiousness", "is_active": true, "created_at": "2025-12-22T16:34:20.317448+00:00", "updated_at": "2025-12-22T16:34:20.317448+00:00", "question_text": "I always arrive on time to scheduled appointments", "reverse_scored": false, "question_number": 1, "question_category": "reliability", "assessment_version": "v1.0"}, {"id": "b7609c87-1e07-45a3-b20a-bb69bc0880b7", "trait": "conscientiousness", "is_active": true, "created_at": "2025-12-22T16:34:20.317448+00:00", "updated_at": "2025-12-22T16:34:20.317448+00:00", "question_text": "I complete projects by the deadline I promised", "reverse_scored": false, "question_number": 2, "question_category": "reliability", "assessment_version": "v1.0"}, {"id": "d86abf74-7f44-4dee-beab-8c8cad8269b5", "trait": "conscientiousness", "is_active": true, "created_at": "2025-12-22T16:34:20.317448+00:00", "updated_at": "2025-12-22T16:34:20.317448+00:00", "question_text": "I keep detailed records of my work and materials used", "reverse_scored": false, "question_number": 3, "question_category": "reliability", "assessment_version": "v1.0"}, {"id": "7b2d45f6-2e97-4dff-9b36-626eb5fbfd69", "trait": "conscientiousness", "is_active": true, "created_at": "2025-12-22T16:34:20.317448+00:00", "updated_at": "2025-12-22T16:34:20.317448+00:00", "question_text": "I prefer to plan my work schedule well in advance", "reverse_scored": false, "question_number": 4, "question_category": "reliability", "assessment_version": "v1.0"}, {"id": "53a2163a-3bb6-47a6-be58-47120a8c1c94", "trait": "conscientiousness", "is_active": true, "created_at": "2025-12-22T16:34:20.317448+00:00", "updated_at": "2025-12-22T16:34:20.317448+00:00", "question_text": "I sometimes forget to follow up with clients after a job", "reverse_scored": true, "question_number": 5, "question_category": "reliability", "assessment_version": "v1.0"}, {"id": "3baffd57-5127-4e44-8081-2c4baf8e3327", "trait": "conscientiousness", "is_active": true, "created_at": "2025-12-22T16:34:20.317448+00:00", "updated_at": "2025-12-22T16:34:20.317448+00:00", "question_text": "I am very organized with my tools and equipment", "reverse_scored": false, "question_number": 6, "question_category": "reliability", "assessment_version": "v1.0"}, {"id": "62911ab4-efee-4802-a5ee-88e0d84d6057", "trait": "conscientiousness", "is_active": true, "created_at": "2025-12-22T16:34:20.317448+00:00", "updated_at": "2025-12-22T16:34:20.317448+00:00", "question_text": "I take pride in leaving a job site clean and tidy", "reverse_scored": false, "question_number": 7, "question_category": "reliability", "assessment_version": "v1.0"}, {"id": "5679b0e5-5bcb-4f60-81ff-bf5988a8296f", "trait": "conscientiousness", "is_active": true, "created_at": "2025-12-22T16:34:20.317448+00:00", "updated_at": "2025-12-22T16:34:20.317448+00:00", "question_text": "I often rush through jobs to move on to the next one", "reverse_scored": true, "question_number": 8, "question_category": "reliability", "assessment_version": "v1.0"}, {"id": "c00d46ac-cd8a-45f0-9c12-5d47d2341925", "trait": "conscientiousness", "is_active": true, "created_at": "2025-12-22T16:34:20.317448+00:00", "updated_at": "2025-12-22T16:34:20.317448+00:00", "question_text": "I double-check my work before considering a job complete", "reverse_scored": false, "question_number": 9, "question_category": "reliability", "assessment_version": "v1.0"}, {"id": "9e0fae79-5049-43d6-8b9b-450058a5b2ab", "trait": "conscientiousness", "is_active": true, "created_at": "2025-12-22T16:34:20.317448+00:00", "updated_at": "2